20	/// Cap the default number of Tokio worker threads if the user did not
21	/// explicitly set `TOKIO_WORKER_THREADS` to avoid spawning too many threads on
22	/// machines with a large number of CPUs, which may lead to excessive context
23	/// switching and degraded performance.
24	fn tokio_worker_threads() -> Option<usize> {
25	    if env::var_os(TOKIO_WORKER_THREADS_ENV).is_some() {
26	        return None;
27	    }
28	
29	    std::thread::available_parallelism()
30	        .map(|parallelism| {
31	            let available = parallelism.get();
32	            let worker_threads = available.min(DEFAULT_MAX_TOKIO_WORKER_THREADS);
33	            if worker_threads < available {
34	                info!(
35	                    available_parallelism = available,
36	                    capped_worker_threads = worker_threads,
37	                    "capping tokio worker threads, set {TOKIO_WORKER_THREADS_ENV} to override"
38	                );
39	            }
40	            worker_threads
41	        })
42	        .ok()
