/// Helper that formats a slice of API keys without revealing their values.
///
/// Renders `[]` for an empty list and `[<redacted>; N]` for a non-empty list,
/// where `N` is the number of configured keys.
struct RedactedApiKeys<'a>(&'a [String]);

impl fmt::Debug for RedactedApiKeys<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.0.is_empty() {
            f.debug_list().finish()
        } else {
            write!(f, "[<redacted>; {}]", self.0.len())
        }
    }
}

/// `educe` debug formatter for [`Config::api_keys`] that never prints the
/// secret key values.
fn fmt_redacted_api_keys(api_keys: &[String], f: &mut fmt::Formatter<'_>) -> fmt::Result {
    fmt::Debug::fmt(&RedactedApiKeys(api_keys), f)
