pub async fn require_api_key(
    State(state): State<Arc<AppState>>,
    req: Request,
    next: Next,
) -> Response {
    // Preflight requests never carry credentials; let them through.
    if req.method() == Method::OPTIONS {
        return next.run(req).await;
