#[serial]
async fn tmp_auth_rejects_missing_and_accepts_valid() {
    let mut app = tmp_auth_app().await;

    // Missing bearer on guarded route -> 401 with the exact JSON body.
    let resp = app
        .call(Request::builder().uri("/v1/models").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::UNAUTHORIZED);
    let body = to_bytes(resp.into_body(), usize::MAX).await.unwrap();
    assert_eq!(&body[..], br#"{"error":"Unauthorized"}"#);

    // Wrong key -> 401
    let resp = app
        .call(
            Request::builder()
                .uri("/v1/models")
                .header("Authorization", "Bearer nope")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::UNAUTHORIZED);

    // Valid key -> 200
    let resp = app
        .call(
            Request::builder()
                .uri("/v1/models")
                .header("Authorization", "Bearer sk-secret")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);

    // Health is unguarded even without a key.
    let resp = app
        .call(Request::builder().uri("/health").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(resp.status(), StatusCode::OK);

    // OPTIONS preflight on a guarded route is allowed through (no 401).
    let resp = app
        .call(
            Request::builder()
                .method("OPTIONS")
                .uri("/v1/models")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_ne!(resp.status(), StatusCode::UNAUTHORIZED);
}

